#!/usr/bin/env python3
"""render_report.py — derive the human-readable drift-report.md from JSON.

The drift-report.json produced by match_drift.py is the single source of truth;
this script renders it to Markdown deterministically (same JSON -> identical MD).
It performs NO analysis and makes NO decisions — presentation only. Consumers
that act on drift read the JSON, not the Markdown.

Usage:
    render_report.py --report FILE [--out FILE]

Exit codes: 0 = rendered; 2 = invalid args / unreadable report.
"""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

_SEV_MARK = {"blocking": "🔴", "major": "🟠", "minor": "🟡"}
_STATUS_LABEL = {
    "missing_in_code": "Not implemented",
    "missing_in_spec": "Undocumented",
    "drifted": "Drifted",
    "undecidable": "Undecidable",
}
_SKIP_ACTION = {
    "draft_status": "Approve via /u-spec before it can be audited",
    "no_code_module": "No code module matched this spec domain — verify naming or implement",
    "no_spec_domain": "Undocumented module — run /u-reverse-spec scoped to it, then approve",
    "parse_failed": "openapi.yaml could not be parsed — fix the spec (or file a parser gap) and re-run; NOT analyzed",
}


def _evidence_str(ev, kind: str) -> str:
    if not ev:
        return "—"
    if kind == "spec":
        anchor = ev.get("anchor", "")
        return f"`{ev.get('file','')}`" + (f"#{anchor}" if anchor else "")
    return f"`{ev.get('file','')}:{ev.get('line','')}`"


def render(report: dict) -> str:
    s = report.get("summary", {})
    lines: list[str] = []
    lines.append("# Spec ↔ Code Drift Report")
    lines.append("")
    lines.append(f"> Generated by `{report.get('generated_by','match_drift.py')}`"
                 + (f" at {report['generated_at']}" if report.get("generated_at") else ""))
    lines.append(">")
    lines.append(f"> Specs: `{report.get('specs_dir','')}` · Code: `{report.get('code_dir','')}`")
    lines.append(f"> spec_content_hash: `{report.get('spec_content_hash','')[:16]}` · "
                 f"code_commit_sha: `{report.get('code_commit_sha','')[:16]}`")
    lines.append("")
    lines.append("## Summary")
    lines.append("")
    lines.append("| Metric | Count |")
    lines.append("|--------|-------|")
    lines.append(f"| Domains analyzed | {s.get('domains_analyzed', 0)} |")
    lines.append(f"| ✅ Aligned | {s.get('aligned', 0)} |")
    lines.append(f"| 🔀 Drifted | {s.get('drifted', 0)} |")
    lines.append(f"| ✗ Not implemented (missing in code) | {s.get('missing_in_code', 0)} |")
    lines.append(f"| 🆕 Undocumented (missing in spec) | {s.get('missing_in_spec', 0)} |")
    lines.append(f"| ❓ Undecidable | {s.get('undecidable', 0)} |")
    lines.append(f"| ⏭ Skipped (draft) | {s.get('skipped_draft', 0)} |")
    lines.append("")

    findings = report.get("findings", [])
    lines.append("## Findings")
    lines.append("")
    if not findings:
        lines.append("_No actionable drift found. Every keyed artifact is present on both sides._")
        lines.append("")
    else:
        domains = sorted({f["domain"] for f in findings})
        for dom in domains:
            lines.append(f"### Domain: {dom}")
            lines.append("")
            lines.append("| ID | Sev | Status | Artifact | Ref | Action | Spec | Code | Detail |")
            lines.append("|----|-----|--------|----------|-----|--------|------|------|--------|")
            for f in [x for x in findings if x["domain"] == dom]:
                lines.append(
                    "| {id} | {sev} | {status} | {atype} | `{ref}` | `{action}` | {spec} | {code} | {detail} |".format(
                        id=f["id"],
                        sev=_SEV_MARK.get(f["severity"], f["severity"]),
                        status=_STATUS_LABEL.get(f["status"], f["status"]),
                        atype=f["artifact_type"],
                        ref=f["artifact_ref"],
                        action=f["default_action"],
                        spec=_evidence_str(f.get("spec_evidence"), "spec"),
                        code=_evidence_str(f.get("code_evidence"), "code"),
                        detail=f["detail"].replace("|", "\\|"),
                    )
                )
            lines.append("")

    aligned = report.get("aligned", [])
    lines.append(f"## Aligned ({len(aligned)})")
    lines.append("")
    if aligned:
        lines.append("| Domain | Artifact | Ref |")
        lines.append("|--------|----------|-----|")
        for a in aligned:
            lines.append(f"| {a['domain']} | {a['artifact_type']} | `{a['artifact_ref']}` |")
        lines.append("")

    skipped = report.get("skipped", [])
    lines.append(f"## Skipped ({len(skipped)})")
    lines.append("")
    if skipped:
        lines.append("| Domain | Reason | Suggested action |")
        lines.append("|--------|--------|------------------|")
        for sk in skipped:
            lines.append(f"| {sk['domain']} | {sk['reason']} | {_SKIP_ACTION.get(sk['reason'], '—')} |")
        lines.append("")

    return "\n".join(lines) + "\n"


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--report", required=True)
    ap.add_argument("--out", help="Write drift-report.md here (default: stdout).")
    args = ap.parse_args(argv)

    try:
        report = json.loads(Path(args.report).read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        print(json.dumps({"status": "error", "reason": "report_unreadable", "detail": str(exc)}))
        return 2

    md = render(report)
    if args.out:
        Path(args.out).write_text(md, encoding="utf-8")
        print(json.dumps({"status": "ok", "out": args.out}))
    else:
        sys.stdout.write(md)
    return 0


if __name__ == "__main__":
    sys.exit(main())
